#include <iostream>
#include <algorithm>
using namespace std;

long long total = 0;

int count_digits(long long number) {
    int count = 0;
    while (number != 0) {
        number /= 10;
        count++;
    }
    return count;
}

long long get_base(long long number) {
    int digits = count_digits(number);
    long long base = 0, multiplier = 1;
    for (int i = 0; i < digits; i++) {
        base += multiplier;
        multiplier *= 10;
    }
    if (base <= number) return base;
    return (base - 1) / 10;
}

long long compute(long long number) {
    if (number <= 6) return number;
    if (number <= 11) return 13 - number;
    long long base_num = get_base(number);
    long long boundary = base_num * 10 + 1;
    if (number % base_num == 0) {
        long long quotient = number / base_num;
        if (number <= boundary / 2 + base_num) return count_digits(base_num) * quotient;
        else {
            long long diff = compute(boundary - number);
            return count_digits(boundary) + diff;
        }
    } else {
        long long lower = (number / base_num) * base_num;
        long long upper = (number / base_num + 1) * base_num;
        long long res = compute(lower) + compute(number - lower);
        if (number > boundary / 2) {
            res = min(compute(lower) + compute(number - lower), count_digits(boundary) + compute(boundary - number));
        }
        return res;
    }
}

int main() {
    long long n;
    cin >> n;
    cout << compute(n) << endl;
    return 0;
}
